import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('starts with owner instructions and rich documentation', async () => {
  const agents = await readFile(new URL('../AGENTS.md', import.meta.url), 'utf8');
  const architecture = await readFile(new URL('../docs/architecture.md', import.meta.url), 'utf8');
  const operations = await readFile(new URL('../docs/operations.md', import.meta.url), 'utf8');
  assert.match(agents, /owner-maintained/);
  assert.match(architecture, /event boundary/);
  assert.match(operations, /Deployment and rollback/);
});
